// one tool, one permission, one output
const proposeEntry = tool({
  name: 'propose_journal_entry',
  description: 'Proposes a balanced journal entry from extracted invoice fields. Does not post.',
  input: z.object({
    vendor: z.string(),
    total:  z.number().positive(),
    vat:    z.number().min(0),
    date:   z.string().date(),
  }),
  // the entry stays a draft until a human approves it
  execute: async (inv) => ledger.draft(balanceEntry(inv)),
});

